 455→async function getTableIntelligence(projectId: string | null | undefined) {
 456→  if (!projectId) {
 457→    return NextResponse.json({ success: true, tables: [], columns: [] });
 458→  }
 459→
 460→  const [tables, columnIntelligence, discoveredTables] = await Promise.all([
 461→    db.toolkitTable.findMany({
 462→      where: { projectId },
 463→      orderBy: { tableName: 'asc' },
 464→    }),
 465→    db.columnIntelligenceCache.findMany(),
 466→    db.discoveredTableCache.findMany({
 467→      where: { projectId },
 468→      orderBy: { priority: 'desc' },
 469→    }),
 470→  ]);
 471→
 472→  // Parse JSON fields in tables
 473→  const parsedTables = tables.map(t => ({
 474→    ...t,
 475→    columns: safeParseJSON(t.columns, []),
 476→    foreignKeys: safeParseJSON(t.foreignKeys, []),
 477→    indexes: safeParseJSON(t.indexes, []),
 478→    constraints: safeParseJSON(t.constraints, []),
 479→  }));
 480→
 481→  // Flatten columns with table context
 482→  const allColumns: any[] = [];
 483→  parsedTables.forEach((t: any) => {
 484→    const cols = t.columns || [];
 485→    cols.forEach((col: any) => {
 486→      const intel = columnIntelligence.find(
 487→        c => c.tableName === t.tableName && c.columnName === col.name
 488→      );
 489→      allColumns.push({
 490→        tableName: t.tableName,
 491→        columnName: col.name,
 492→        dataType: col.dataType,
 493→        nullable: col.nullable,
 494→        isPrimaryKey: col.isPrimaryKey,
 495→        isIdentity: col.isIdentity,
 496→        defaultValue: col.defaultValue,
 497→        ...intel ? {
 498→          semanticType: intel.semanticType,
 499→          uiType: intel.uiType,
 500→          sensitivity: intel.sensitivity,
 501→          confidence: intel.confidence,
 502→          isSearchable: intel.isSearchable,
 503→          isFilterable: intel.isFilterable,
 504→          displayInList: intel.displayInList,
 505→        } : {},
 506→      });
 507→    });
 508→  });
 509→
 510→  return NextResponse.json({
 511→    success: true,
 512→    tables: parsedTables,
 513→    columns: allColumns,
 514→    discoveredTables,
 515→    summary: {
 516→      totalTables: tables.length,
 517→      totalColumns: allColumns.length,
 518→      totalDiscovered: discoveredTables.length,
 519→      modulesLinked: tables.filter((t: any) => t.linkedModule).length,
 520→    },
 521→  });
 522→}
