 668→
 669→async function getFKResolutionData(projectId: string | null | undefined) {
 670→  if (!projectId) {
 671→    return NextResponse.json({ success: true, data: {} });
 672→  }
 673→
 674→  const [tables, discoveredTables, fkDependencyCaches, fkResolutionSessions, missingTableResolutions] = await Promise.all([
 675→    db.toolkitTable.findMany({
 676→      where: { projectId },
 677→      select: { tableName: true, foreignKeys: true },
 678→    }),
 679→    db.discoveredTableCache.findMany({ where: { projectId } }),
 680→    db.fKDependencyCache.findMany({ where: { projectId } }),
 681→    db.fKResolutionSession.findMany({ where: { projectId } }),
 682→    db.missingTableResolution.findMany({ where: { projectId } }),
 683→  ]);
 684→
 685→  // Calculate FK resolution
 686→  const tableNames = new Set(tables.map(t => t.tableName.toLowerCase()));
 687→  let totalFKs = 0;
 688→  let resolvedFKs = 0;
 689→  const missingTables = new Map<string, { referencedBy: string[], count: number }>();
 690→
 691→  tables.forEach(t => {
 692→    const fks = safeParseJSON(t.foreignKeys, []);
 693→    fks.forEach((fk: any) => {
 694→      totalFKs++;
 695→      const refTable = fk.referencesTable?.toLowerCase();
 696→      if (tableNames.has(refTable)) {
 697→        resolvedFKs++;
 698→      } else {
 699→        const existing = missingTables.get(refTable) || { referencedBy: [], count: 0 };
 700→        existing.referencedBy.push(t.tableName);
 701→        existing.count++;
 702→        missingTables.set(refTable, existing);
 703→      }
 704→    });
 705→  });
 706→
 707→  return NextResponse.json({
 708→    success: true,
 709→    data: {
 710→      totalFKs,
 711→      resolvedFKs,
 712→      unresolvedFKs: totalFKs - resolvedFKs,
 713→      resolutionPercent: totalFKs > 0 ? Math.round((resolvedFKs / totalFKs) * 100) : 0,
 714→      missingTables: Array.from(missingTables.entries()).map(([name, data]) => ({
 715→        tableName: name,
 716→        referencedBy: data.referencedBy,
 717→        referenceCount: data.count,
 718→      })),
 719→      discoveredTables,
 720→      dependencyCaches: fkDependencyCaches,
 721→      sessions: fkResolutionSessions,
 722→      resolutions: missingTableResolutions,
 723→    },
 724→  });
 725→}
