 965→function calculateFKResolution(tables: any[], discoveredTables: any[]) {
 966→  const tableNames = new Set(tables.map((t: any) => t.tableName.toLowerCase()));
 967→  let total = 0;
 968→  let resolved = 0;
 969→  const missing: string[] = [];
 970→
 971→  tables.forEach((t: any) => {
 972→    try {
 973→      const fks = JSON.parse(t.foreignKeys || '[]');
 974→      fks.forEach((fk: any) => {
 975→        total++;
 976→        if (tableNames.has(fk.referencesTable?.toLowerCase())) {
 977→          resolved++;
 978→        } else {
 979→          missing.push(fk.referencesTable);
 980→        }
 981→      });
 982→    } catch (e) {
 983→      // Skip
 984→    }
 985→  });
 986→
 987→  return {
 988→    total,
 989→    resolved,
 990→    percent: total > 0 ? Math.round((resolved / total) * 100) : 0,
 991→    missing: [...new Set(missing)],
 992→  };
 993→}
 994→
 995→function calculateModuleCoverage(tables: any[]) {
 996→  const HIS_MODULE_COUNT = 35; // Standard HIS module count
 997→  const modulesWithTables = new Set<string>();
 998→
 999→  tables.forEach((t: any) => {
1000→    if (t.linkedModule) {
1001→      modulesWithTables.add(t.linkedModule);
1002→    }
1003→  });
1004→
1005→  return {
1006→    linked: modulesWithTables.size,
1007→    total: HIS_MODULE_COUNT,
1008→    percent: Math.round((modulesWithTables.size / HIS_MODULE_COUNT) * 100),
1009→  };
1010→}
