1012→function calculateHealthScore(data: {
1013→  totalTables: number;
1014→  totalFKs: number;
1015→  fkResolved: number;
1016→  fkTotal: number;
1017→  modulesLinked: number;
1018→  modulesTotal: number;
1019→  spsAnalyzed: number;
1020→  viewsAnalyzed: number;
1021→  qualityScore: number | null | undefined;
1022→}): number {
1023→  if (data.totalTables === 0) return 0;
1024→
1025→  const weights = {
1026→    fkResolution: 0.3,
1027→    moduleCoverage: 0.25,
1028→    spAnalysis: 0.2,
1029→    viewAnalysis: 0.15,
1030→    quality: 0.1,
1031→  };
1032→
1033→  const fkScore = data.fkTotal > 0 ? (data.fkResolved / data.fkTotal) * 100 : 100;
1034→  const moduleScore = (data.modulesLinked / data.modulesTotal) * 100;
1035→  const spScore = data.totalTables > 0 ? Math.min(100, (data.spsAnalyzed / data.totalTables) * 50) : 0;
1036→  const viewScore = data.totalTables > 0 ? Math.min(100, (data.viewsAnalyzed / data.totalTables) * 50) : 0;
1037→  const qualityScore = data.qualityScore ? data.qualityScore * 100 : 50;
1038→
1039→  const healthScore = 
1040→    fkScore * weights.fkResolution +
1041→    moduleScore * weights.moduleCoverage +
1042→    spScore * weights.spAnalysis +
1043→    viewScore * weights.viewAnalysis +
1044→    qualityScore * weights.quality;
1045→
1046→  return Math.round(healthScore);
1047→}
