1049→function safeParseJSON(str: string | null | undefined, defaultValue: any) {
1050→  if (!str) return defaultValue;
1051→  try {
1052→    return JSON.parse(str);
1053→  } catch {
1054→    return defaultValue;
1055→  }
1056→}
