1058→function groupBy(arr: any[], key: string): Record<string, number> {
1059→  const result: Record<string, number> = {};
1060→  arr.forEach(item => {
1061→    const k = (item as any)[key] || 'unknown';
1062→    result[k] = (result[k] || 0) + 1;
1063→  });
1064→  return result;
1065→}
