            Reports
          </TabsTrigger>
          <TabsTrigger value="prevention">
            <Shield className="h-4 w-4 mr-2" />
            Prevention
          </TabsTrigger>
          <TabsTrigger value="compare">
            <TrendingUp className="h-4 w-4 mr-2" />
            Compare
